INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2718136', 'Yawm al-Buath', 'The Yawm al-Buʿāth (Arabic: معرکة بُعاث) was a pre-Islamic Arabian battle fought in 617 in Medina between the two dominant tribes living there, the Aws and the Khazraj. The battle marked the final armed conflict between both tribes before their conversion to Islam after the arrival of the Islamic prophet Muhammad.', 617, NULL, NULL, NULL, NULL, NULL, 'year', '617', 47, 'https://en.wikipedia.org/wiki/Yawm_al-Buath'),
  ('Q486124', 'Battle of Badr', 'The Battle of Badr or sometimes called The Raid of Badr (Arabic: غَزْوَةُ بَدْرٍ [ɣazwatu badr]; Ghazwatu Badr), also referred to as The Day of the Criterion (Arabic: يَوْمُ الْفُرْقَانْ, Arabic pronunciation: [jawm''ul fur''qaːn]; Yawm al-Furqan) in the Qur''an and by Muslims, was fought on 13 March 624 CE (17 Ramadan, 2 AH), near the city of Badr, Medina Province in present-day Saudi Arabia. Muhammad, commanding an army of his Sahaba, defeated an army of the Quraysh led by Amr ibn Hisham, better known among Muslims as Abu Jahl.', 624, 3, 12, NULL, NULL, NULL, 'day', '12 March 624', 83, 'https://en.wikipedia.org/wiki/Battle_of_Badr'),
  ('Q3079892', 'Invasion of Banu Qaynuqa', 'The siege of Banu Qaynuqa occurred in April 624. The Banu Qaynuqa were a Jewish tribe expelled by the Islamic prophet Muhammad for breaking the treaty known as the Constitution of Medina.', 624, NULL, NULL, NULL, NULL, NULL, 'year', '624', 57, 'https://en.wikipedia.org/wiki/Siege_of_Banu_Qaynuqa'),
  ('Q4704263', 'Al Kudr Invasion', 'The expedition against the Banu Salim tribe, also known as the Al Kudr Invasion, occurred directly after the Battle of Badr in the year AH 2 of the Islamic calendar. The expedition was ordered by the Islamic prophet Muhammad after he received intelligence that the Banu Salim were planning to invade Madina.', 624, 4, 1, NULL, NULL, NULL, 'day', '1 April 624', 47, 'https://en.wikipedia.org/wiki/Al_Kudr_Invasion'),
  ('Q6059603', 'Invasion of Bahran', 'The Invasion of Buhran occurred in 3 A.H of the Islamic calendar of the 4th or 5th month. A report had arrived to the Muslims that a formidable force of the Banu Sulaym from Buhran were advancing on Madinah.', 624, 10, NULL, 624, 11, NULL, 'month', 'October 624 – November 624', 50, 'https://en.wikipedia.org/wiki/Invasion_of_Buhran'),
  ('Q488278', 'Battle of Uhud', 'The Battle of Uhud (Arabic: غزوة أحد, romanized: Ghazwat ʾUḥud) was fought between the early Muslims and the Quraysh during the Muslim–Quraysh wars in a valley north of Medina near Mount Uhud on Saturday, 23 March 625 AD (7 Shawwal, 3 AH). Following the Muslim emigration to Medina, hostilities with the Quraysh intensified, largely due to Muslim raids on Meccan trade caravans.', 625, 3, 23, NULL, NULL, NULL, 'day', '23 March 625', 79, 'https://en.wikipedia.org/wiki/Battle_of_Uhud'),
  ('Q3153830', 'Invasion of Dumatul Jandal', 'The Expedition of Dumat al-Jandal is an early Muslim expedition which took place in August or September of 626 AD. According to Indian biographer of the Islamic prophet Muhammad, Safiur Rahman Mubarakpuri, Dumat al-Jandal is located at about a distance of fifteen days'' march from Medina and five from Damascus. According to historian William Montgomery Watt, it is 500 miles from Medina.', 626, NULL, NULL, NULL, NULL, NULL, 'year', '626', 50, 'https://en.wikipedia.org/wiki/Expedition_of_Dumat_al-Jandal'),
  ('Q826083', 'Battle of the Trench', 'The Battle of the Trench (Arabic: غزوة الخندق, romanized: Ghazwat al-Khandaq), also known as the Battle of Khandaq (Arabic: معركة الخندق, romanized: Maʿrakah al-Khandaq) and the Battle of the Confederates (Arabic: غزوة الاحزاب, romanized: Ghazwat al-Aḥzāb), was part of the conflict between the Muslims and the Quraysh. The Quraysh advanced towards the Muslims, who defended themselves in Medina by digging a trench around their settlement at the suggestion of Salman the Persian.', 627, NULL, NULL, NULL, NULL, NULL, 'year', '627', 76, 'https://en.wikipedia.org/wiki/Battle_of_the_Trench'),
  ('Q2092033', 'Conquest of Mecca', 'The conquest of Mecca (Arabic: فتح مكة Fatḥ Makka) was a military campaign undertaken by Muhammad and his companions during the Muslim–Quraysh War. They led the early Muslims in an advance on the Quraysh-controlled city of Mecca in December 629 or January 630 (10–20 Ramadan, 8 AH).', 629, NULL, NULL, NULL, NULL, NULL, 'year', '629', 71, 'https://en.wikipedia.org/wiki/Conquest_of_Mecca'),
  ('Q3087968', 'Siege of Ta''if', 'The Siege of Ta''if took place in 630 CE, shortly after the Muslim victory at the battles of Hunayn and Autas that followed the conquest of Mecca. Seeking to consolidate control over the Hijaz, Muhammad marched with his forces to the fortified city of Ta''if, stronghold of the Thaqif tribe and a long-standing commercial rival of Mecca.', 630, 12, NULL, NULL, NULL, NULL, 'month', 'December 630', 57, 'https://en.wikipedia.org/wiki/Siege_of_Ta''if'),
  ('Q3696185', 'Battle of Buzakha', 'The Battle of Buzakha was a major military battle in the Ridda Wars or Wars of Apostasy. It took place between the army of the Rashidun Caliphate under command of Khalid ibn al-Walid and the Apostate forces under Tulayha, in September 632.', 632, 9, 1, NULL, NULL, NULL, 'day', '1 September 632', 50, 'https://en.wikipedia.org/wiki/Battle_of_Buzakha'),
  ('Q3696202', 'Battle of Dawmat al-Jandal', 'The Battle of Daumat al-Jandal took place between Muslims and Rebel Arab tribes in August 633 CE. This was a part of the Riddah wars. Daumat al-Jandal was given to Iyad ibn Ghanm to crush the rebels, but he failed in doing so, and sent for help to Khalid ibn Walid who was in Iraq in those days.', 633, 8, NULL, NULL, NULL, NULL, 'month', 'August 633', 45, 'https://en.wikipedia.org/wiki/Battle_of_Dawmat_al-Jandal'),
  ('Q4871866', 'Battle of Naqra', 'The Battle of Naqra took place in October 633 between rebel armies and Khalid ibn al-Walid''s army during the Ridda Wars. After the defeat of Tulayha in the Battle of Buzakha, the tribe Banu Sulaym under the leadership of Amr bin Abdul Uzza(Abu Shajara) remained defiant to oppose the force led by Khalid ibn Walid.', 633, 10, 1, NULL, NULL, NULL, 'day', '1 October 633', 41, 'https://en.wikipedia.org/wiki/Battle_of_Naqra'),
  ('Q3625539', 'Siege of Uthman', 'Uthman ibn Affan, the third Rashidun caliph, who ruled from 644 to 656, was assassinated at the end of a siege upon his house in 656. This was initially a protest but escalated into a siege following the death of a protester.', 656, 6, 17, NULL, NULL, NULL, 'day', '17 June 656', 53, 'https://en.wikipedia.org/wiki/Assassination_of_Uthman'),
  ('Q514382', 'Battle of al-Harrah', 'The Battle of al-Harra (Arabic: يوم الحرة, romanized: Yawm al-Ḥarra, lit. ''Day of al-Harra'') was fought between the Umayyad army of the caliph Yazid I (r. 680–683) led by Muslim ibn Uqba and the defenders of Medina from the Ansar and Muhajirun factions, who had rebelled against the caliph. The battle took place at the lava field of Harrat Waqim in the northeastern outskirts of Medina on 26 August 683 and lasted less than a day.', 683, NULL, NULL, NULL, NULL, NULL, 'year', '683', 56, 'https://en.wikipedia.org/wiki/Battle_of_al-Harra'),
  ('Q3023525', 'Siege of Mecca', 'The siege of Mecca in September–November 683 was one of the early battles of the Second Fitna. The city of Mecca was a sanctuary for Abd Allah ibn al-Zubayr, who was among the most prominent challengers to the hereditary succession to the Caliphate by Yazid I of the Umayyad dynasty.', 683, 9, 24, 683, 11, 26, 'day', '24 September 683 – 26 November 683', 52, 'https://en.wikipedia.org/wiki/Siege_of_Mecca_(683)'),
  ('Q17019401', 'Siege of Mecca', 'The siege of Mecca in March–October/November 692 was the final battle of the Second Fitna, in which the forces of the Umayyad caliph Abd al-Malik ibn Marwan besieged and defeated his rival, caliph Abd Allah ibn al-Zubayr in his center of power, the Islamic holy city of Mecca. Following the death of Caliph Yazid I in 683, Ibn al-Zubayr had been recognized as caliph in most of the provinces of the Caliphate, while the Umayyads, who had ruled the Caliphate since the end of the First Fitna, were confined to their stronghold of Syria.', 692, NULL, NULL, 692, 10, 4, 'year', '692', 52, 'https://en.wikipedia.org/wiki/Siege_of_Mecca_(692)'),
  ('Q19610920', 'Siege of Jeddah', 'The siege of Jeddah was a naval battle that took place in the harbor of Jeddah between a Portuguese expeditionary force under Lopo Soares de Albergaria and Ottoman elements under Selman Reis, and Egyptian Mamluks fleet. The Portuguese fleet arrived off the city’s coast on Easter day, 1517 (12 April), Hijri year 923, and moored in the channel.', 1517, 4, 12, NULL, NULL, NULL, 'day', '12 April 1517', 39, 'https://en.wikipedia.org/wiki/Siege_of_Jeddah'),
  ('Q1809288', 'Ottoman–Wahhabi war', 'The Ottoman–Wahhabi war, or Wahhabi war, was fought from early 1811 until 1818 between the Ottoman Empire, its vassal the Eyalet of Egypt, and the Wahhabis’ Emirate of Diriyah (later known as the first Saudi state), resulting in the destruction of the latter.', 1811, 8, NULL, 1818, 8, NULL, 'month', 'August 1811 – August 1818', 64, 'https://en.wikipedia.org/wiki/Ottoman%E2%80%93Wahhabi_war'),
  ('Q3656327', 'Battle of Yanbu', 'The Capture of Yanbu, or Yanbu Landing, in 1811 was a military engagement that began the First Campaign of the Ottoman–Wahhabi war. It occurred with virtually no resistance as the Wahhabis had no troops in the area when the Ottomans initially arrived.', 1811, NULL, NULL, NULL, NULL, NULL, 'year', '1811', 37, 'https://en.wikipedia.org/wiki/Capture_of_Yanbu_(1811)'),
  ('Q3656325', 'Battle of Medina', 'The Battle of Medina in 1812 was part of the First Campaign of the Ottoman–Wahhabi war. Following his defeat at the Battle of Al-Safra, Tusun Pasha''s forces regrouped and made another attempt to reach Saud''s Wahhabi forces in Medina.', 1812, 11, NULL, NULL, NULL, NULL, 'month', 'November 1812', 45, 'https://en.wikipedia.org/wiki/Battle_of_Medina_(1812)'),
  ('Q3608484', 'Battle of Mecca', 'The Capture of Mecca in 1813 took place several days after the Ottoman Capture of Jeddah in the First Campaign of the Ottoman–Wahhabi war.', 1813, NULL, NULL, NULL, NULL, NULL, 'year', '1813', 48, 'https://en.wikipedia.org/wiki/Capture_of_Mecca_(1813)'),
  ('Q3656242', 'Battle of Jeddah', 'The Capture of Jeddah, a west Arabian (Hejaz) port City, occurred in 1813. It occurred with no casualties in the First Campaign of the Ottoman-Wahhabi war.', 1813, NULL, NULL, NULL, NULL, NULL, 'year', '1813', 43, 'https://en.wikipedia.org/wiki/Capture_of_Jeddah_(1813)'),
  ('Q3656346', 'Siege of Diriyah', 'The siege of Diriyah was a successful Ottoman siege that took place in late 1818 at the end of the Wahhabi War of 1811–1818 during the Nejd Expedition.', 1818, 4, NULL, 1818, 9, 15, 'month', 'April 1818 – 15 September 1818', 37, 'https://en.wikipedia.org/wiki/Siege_of_Diriyah'),
  ('Q654722', 'Battle of Mulayda', 'The Battle of Mulayda was the last major battle during the period of the Second Saudi State which occurred on 21 January 1891 over issues regarding zakat and the arrest of the Rashidi leader. The Rashidis plotted to end the Saudi state and conquer both the Qassim region and Riyadh.', 1891, 1, 24, NULL, NULL, NULL, 'day', '24 January 1891', 43, 'https://en.wikipedia.org/wiki/Battle_of_Mulayda'),
  ('Q2943187', 'Battle of Riyadh', 'The Battle of Riyadh or the Reconquest of Riyadh, was fought on 13 January 1902 in Riyadh, then part of the Emirate of Jabal Shammar. It was a conflict between the Rashidi dynasty and the House of Saud, and ended with Ibn Saud successfully capturing the walled city.', 1902, 1, 13, NULL, NULL, NULL, 'day', '13 January 1902', 45, 'https://en.wikipedia.org/wiki/Battle_of_Riyadh'),
  ('Q4870874', 'Battle of Dilam', 'The Battle of Dilam was a battle fought on 27 January 1903 between the Third Saudi State under Ibn Saud and the Emirate of Jabal Shammar under Abdulaziz bin Mutaib during the Unification of Saudi Arabia. The battle took place at Ad-Dilam, south of Riyadh, and ended in a Saudi victory.', 1903, 1, 27, NULL, NULL, NULL, 'day', '27 January 1903', 34, 'https://en.wikipedia.org/wiki/Battle_of_Dilam'),
  ('Q4870449', 'Battle of Bekeriyah', 'Battle of al-Bukayriyya was a major battle of the 1903–1907 Saudi–Rashidi War, during the Unification of Saudi Arabia campaign, fought between the ruling Rashidi dynasty and the Saudi rebels. It occurred in July 1904 at the town of Bekeriyah in the Qassim region.', 1904, 6, 15, NULL, NULL, NULL, 'day', '15 June 1904', 34, 'https://en.wikipedia.org/wiki/Battle_of_al-Bukayriyya'),
  ('Q4872369', 'Battle of Shinanah', 'The Battle of Shinanah was a major battle of the Saudi–Rashidi War, during the Unification of Saudi Arabia campaign, between the Rashidi dynasty and Saudi rebels. It occurred on 29 September 1904, in the town of Shinanah in Qassim region.', 1904, 9, 29, NULL, NULL, NULL, 'day', '29 September 1904', 37, 'https://en.wikipedia.org/wiki/Battle_of_Shinanah_(1904)'),
  ('Q4872631', 'Battle of Unaizah', 'The Battle of Unaizah (Arabic: معركة عنيزة) took place during the early stage of the Saudi-Rashidi War. Abdulaziz captured Unaizah (Anaiza) in March 1904, killing 370 while losing only two men.', 1904, 3, NULL, NULL, NULL, NULL, 'month', 'March 1904', 37, 'https://en.wikipedia.org/wiki/Battle_of_Unaizah_(1904)'),
  ('Q3636596', 'Battle of Rawdat Muhanna', 'The Battle of Rawdat Muhanna (Arabic: معركة روضة مهنا or Arabic: معركة روضة ابن مهنا) was a major battle of the Saudi–Rashidi War, during the unification of Saudi Arabia, fought between the Rashidi dynasty and Saudi rebels. It occurred on 12 April 1906, in Muhanna''s Gardens in Qassim region.', 1906, 4, 12, NULL, NULL, NULL, 'day', '12 April 1906', 39, 'https://en.wikipedia.org/wiki/Battle_of_Rawdat_Muhanna'),
  ('Q2888986', 'Battle of Kunfuda Bay', 'The Battle of Kunfuda Bay was a naval battle of the Italo-Turkish War between small squadrons of the Italian and Ottoman navies. On 7 January 1912, the Italian protected cruiser Piemonte and the Soldato-class destroyers Artigliere and Garibaldino, cruising the Red Sea, discovered six Ottoman gunboats, a tugboat, and a yacht in the harbor at Kunfuda.', 1912, 1, 7, 1912, 1, 8, 'day', '7 January 1912 – 8 January 1912', 45, 'https://en.wikipedia.org/wiki/Battle_of_Kunfuda_Bay'),
  ('Q2089011', 'Siege of Medina', 'The siege of Medina lasted from 10 June 1916 to 10 January 1919, when Hejazi Arab rebels surrounded the Islamic holy city, which was then under the control of the Ottoman Empire. The Ottoman Empire joined the war on the side of the Central Powers under the leadership of the Ottoman Sultan, Mehmed V. In an attempt to weaken the Ottomans, the Allies provoked an Arab Revolt within the empire led by Sharif Hussein bin Ali of Mecca.', 1916, 6, 10, 1919, 1, 10, 'day', '10 June 1916 – 10 January 1919', 56, 'https://en.wikipedia.org/wiki/Siege_of_Medina'),
  ('Q2089020', 'Battle of Mecca', 'The Battle of Mecca occurred in the Muslim holy city of Mecca in June and July 1916. On June 10, the Sharif of Mecca, Hussein bin Ali, the leader of the Banu Hashim clan, started a revolt against the Ottoman Caliphate from this city.', 1916, 6, 10, 1916, 7, 4, 'day', '10 June 1916 – 4 July 1916', 53, 'https://en.wikipedia.org/wiki/Battle_of_Mecca_(1916)'),
  ('Q3695659', 'Battle of Taif', 'The Battle of Taif was fought between Ottoman forces and Syed Hussien bin Ali Sharif of Mecca in 1916. The Ottoman Army was in Taif, with Syed''s forces besieging the city and after many weeks siege and fiercest struggle Syed''s forces were able to capture the Taif.', 1916, 6, 10, 1916, 9, 23, 'day', '10 June 1916 – 23 September 1916', 41, 'https://en.wikipedia.org/wiki/Battle_of_Taif_(1916)'),
  ('Q5162436', 'Conquest of Ha''il', 'The Saudi conquest of Hail, also known as the Third Saudi–Rashidi War or the Fall of Hail, was a conflict between the Third Saudi State and the Emirate of Jabal Shammar, led by its final Rashidi ruler, Muhammad bin Talal. The Saudi forces were led by Ibn Saud.', 1921, NULL, NULL, NULL, NULL, NULL, 'year', '1921', 34, 'https://en.wikipedia.org/wiki/Saudi_conquest_of_Hail'),
  ('Q4871705', 'Battle of Mecca', 'The Capture of Mecca took place on 5 December 1924 in Mecca, as part of the Saudi conquest of the Kingdom of Hejaz by King Abdulaziz Ibn Saud of the Sultanate of Nejd. The Hejaz region was ruled as a kingdom under King Hussein bin Ali of the Hashemite family.', 1924, NULL, NULL, NULL, NULL, NULL, 'year', '1924', 48, 'https://en.wikipedia.org/wiki/Capture_of_Mecca_(1924)'),
  ('Q4871317', 'Battle of Jeddah', 'The Battle of Jeddah or the siege of Jeddah took place in 1925, as part of the Abdulaziz Ibn Saud''s campaign to conquer the Kingdom of Hejaz. Jeddah was the last major stand of the Hashemites against the Saudis.', 1925, 2, 10, 1925, 12, 17, 'day', '10 February 1925 – 17 December 1925', 43, 'https://en.wikipedia.org/wiki/Battle_of_Jeddah_(1925)'),
  ('Q3636603', 'Battle of Sabilla', 'The Battle of Sabilla (29–31 March 1929) was the main battle of the Ikhwan revolt in northern Arabia between the rebellious Ikhwan forces and the army of Abdulaziz al-Saud. It was the last tribal uprising in Arabia.', 1929, 3, 29, 1929, 3, 31, 'day', '29 March 1929 – 31 March 1929', 39, 'https://en.wikipedia.org/wiki/Battle_of_Sabilla'),
  ('Q1367731', 'Saudi–Yemeni War', 'The Saudi–Yemeni war (Arabic: الحرب السعودية اليمنية) was a war between the Kingdom of Saudi Arabia and the Kingdom of Yemen in 1934.', 1934, 3, NULL, 1934, 5, 20, 'month', 'March 1934 – 20 May 1934', 55, 'https://en.wikipedia.org/wiki/Saudi%E2%80%93Yemeni_war_(1934)'),
  ('Q521199', 'North Yemen civil war', 'The North Yemen civil war, also known in Yemen as the 26 September Revolution, was a civil war fought in North Yemen from 1962 to 1970 between partisans of the Mutawakkilite Kingdom and supporters of the Yemen Arab Republic. The war began with a coup d''état carried out in 1962 by revolutionary republicans led by the army under the command of Abdullah al-Sallal.', 1962, 9, 26, 1970, 12, 1, 'day', '26 September 1962 – 1 December 1970', 67, 'https://en.wikipedia.org/wiki/North_Yemen_civil_war'),
  ('Q6841321', 'Middle East Airlines Flight 438', 'Middle East Airlines Flight 438 was an international passenger flight operated by a Boeing 720 from Beirut, Lebanon, to Muscat, Oman, with a stopover in Abu Dhabi, United Arab Emirates. On 1 January 1976, the aircraft operating the flight was destroyed at 11,300 feet by a bomb, killing all 81 people on board.', 1976, 1, 1, NULL, NULL, NULL, 'day', '1 January 1976', 47, 'https://en.wikipedia.org/wiki/Middle_East_Airlines_Flight_438'),
  ('Q829839', 'Grand Mosque Seizure', 'The Grand Mosque seizure took place between 20 November and 4 December 1979 at the Grand Mosque of Mecca in Mecca, Saudi Arabia, the holiest site in Islam. The attack was carried out by up to 600 militants led by Juhayman al-Otaybi, a Saudi Islamist opposed to the monarchy, belonging to the Otaibah tribe.', 1979, 12, 4, 1979, 12, 4, 'day', '4 December 1979', 69, 'https://en.wikipedia.org/wiki/Grand_Mosque_seizure'),
  ('Q7119313', 'PIA Flight 740', 'On 26 November 1979, Pakistan International Airlines Flight 740, a Boeing 707 operating a scheduled international passenger flight from Kano, Nigeria, to Karachi, Pakistan, via Jeddah, Saudi Arabia, crashed near Taif after attempting to return to Jeddah International Airport following an in-flight fire, killing all 145 passengers and 11 crew members. Around eighteen minutes after taking off from Jeddah, a flight attendant reported to the flight crew that a fire had started in the aft section of the aircraft.', 1979, 11, 26, NULL, NULL, NULL, 'day', '26 November 1979', 56, 'https://en.wikipedia.org/wiki/Pakistan_International_Airlines_Flight_740'),
  ('Q42378014', 'Qatif conflict', 'The Qatif conflict is a modern phase of sectarian tensions and violence in Eastern Arabia between Arab Shia Muslims and the Arab Sunni majority, which has ruled Saudi Arabia since early 20th century. The conflict encompasses civil unrest which has been sporadically happened since the 1979 uprising, pro-democracy and pro-human rights protests and occasional armed incidents, which increased in 2017 as part of the 2017–20 Qatif unrest.', 1979, 11, 26, NULL, NULL, NULL, 'day', '26 November 1979', 37, 'https://en.wikipedia.org/wiki/Qatif_conflict'),
  ('Q2440618', 'Saudia Flight 163', 'Saudia Flight 163 was a scheduled Saudia passenger flight departing from Quaid-e-Azam Airport in Karachi, Pakistan, bound for Kandara Airport in Jeddah, Saudi Arabia, via then-Riyadh International Airport in Riyadh, Saudi Arabia, which caught fire after takeoff on 19 August 1980. Although the Lockheed L-1011 TriStar made a successful emergency landing at Riyadh, the flight crew failed to perform an emergency evacuation of the airplane, leading to the deaths of all 287 passengers and 14 crew on board the aircraft from smoke inhalation.', 1980, 8, 19, NULL, NULL, NULL, 'day', '19 August 1980', 63, 'https://en.wikipedia.org/wiki/Saudia_Flight_163'),
  ('Q6067958', 'Iraqi Airways Flight 163', 'Iraqi Airways Flight 163 was a Boeing 737-200, registered YI-AGJ, that was hijacked in 1986. On 25 December 1986, en route from Baghdad''s Saddam International Airport to Amman, Jordan, Flight 163 was hijacked by four men.', 1986, 12, 25, NULL, NULL, NULL, 'day', '25 December 1986', 50, 'https://en.wikipedia.org/wiki/Iraqi_Airways_Flight_163'),
  ('Q37643', 'Gulf War', 'The Gulf War was an armed conflict between Iraq and a 42-country coalition led by the United States in response to the Iraqi invasion of Kuwait on 2 August 1990. The coalition''s efforts were carried out in two phases: Operation Desert Shield, which marked the military buildup in the Persian Gulf region from August 1990 to January 1991; and Operation Desert Storm, which began with the bombing campaign against Iraq on 17 January and continued until the liberation of Kuwait on 28 February.', 1990, 8, 2, 1991, 2, 28, 'day', '2 August 1990 – 28 February 1991', 90, 'https://en.wikipedia.org/wiki/Gulf_War'),
  ('Q718770', 'Battle of Khafji', 'The Battle of Khafji was the first major ground engagement of the Gulf War. It took place in and around the Saudi Arabian city of Khafji, from 29 January to 1 February 1991.', 1991, 1, 29, 1991, 2, 1, 'day', '29 January 1991 – 1 February 1991', 57, 'https://en.wikipedia.org/wiki/Battle_of_Khafji'),
  ('Q2634895', 'Nigeria Airways Flight 2120', 'Nigeria Airways Flight 2120 was a chartered passenger flight from Jeddah, Saudi Arabia, to Sokoto, Nigeria. On 11 July 1991, the Douglas DC-8 operating the flight, registered as C-GMXQ and operated by Nationair Canada for Nigeria Airways, caught fire shortly after takeoff from King Abdulaziz International Airport, and crashed while attempting to return for an emergency landing, killing all 247 passengers and 14 crew members on board.', 1991, 7, 11, NULL, NULL, NULL, 'day', '11 July 1991', 58, 'https://en.wikipedia.org/wiki/Nigeria_Airways_Flight_2120'),
  ('Q2566144', '2002 Mecca girls'' school fire', 'A fire on 11 March 2002 at a girls'' school in Mecca, Saudi Arabia, killed fifteen people, all young girls. Complaints were made that Saudi Arabia''s "religious police", specifically the Committee for the Promotion of Virtue and the Prevention of Vice, had prevented schoolgirls from leaving the burning building and hindered emergency services personnel because the students were not wearing modest clothing.', 2002, 3, 11, NULL, NULL, NULL, 'day', '11 March 2002', 45, 'https://en.wikipedia.org/wiki/2002_Mecca_girls''_school_fire'),
  ('Q333363', '2009 Jeddah floods', 'The 2009 Saudi Arabian floods affected Jeddah, on the Red Sea (western) coast of Saudi Arabia, and other areas of Makkah Province. They have been described by civil defence officials as the worst in 27 years.', 2009, 11, 25, NULL, NULL, NULL, 'day', '25 November 2009', 43, 'https://en.wikipedia.org/wiki/2009_Jeddah_floods'),
  ('Q1779841', 'Lufthansa Cargo Flight 8460', 'Lufthansa Cargo Flight 8460 was an international cargo flight operated by a McDonnell Douglas MD-11 which crashed upon landing in Riyadh, Saudi Arabia on 27 July 2010. Both crew members, the only people on board, were injured but survived.', 2010, 7, 27, NULL, NULL, NULL, 'day', '27 July 2010', 52, 'https://en.wikipedia.org/wiki/Lufthansa_Cargo_Flight_8460'),
  ('Q20966269', 'Mecca crane collapse', 'A crawler crane collapsed over the Masjid al-Haram in Mecca, Saudi Arabia, around 5:10 p.m. on 11 September 2015, killing 111 people and injuring 394 others.', 2015, 9, 11, NULL, NULL, NULL, 'day', '11 September 2015', 67, 'https://en.wikipedia.org/wiki/Mecca_crane_collapse'),
  ('Q44407676', 'Battle of Sana''a', 'The Battle of Sanaa in 2017 was fought between forces loyal to Ali Abdullah Saleh and the Houthis in the Yemeni capital of Sanaa. Both sides were allied during the 2014–15 Houthi takeover of the government but the alliance ended when Saleh decided to break ranks with the Houthis and call for dialogue with Saudi Arabia and the United Arab Emirates, who are leading a military intervention in Yemen.', 2017, 11, 29, 2017, 12, 4, 'day', '29 November 2017 – 4 December 2017', 37, 'https://en.wikipedia.org/wiki/Battle_of_Sanaa_(2017)'),
  ('Q48735086', 'Battle of Al Hudaydah', 'The siege of Hodeidah, also called Hudaydah or al-Hudaydah, (Arabic: معركة الحديدة, romanized: Ma‘rakat al-Ḥudaydah), codenamed Operation Golden Victory, was a major Saudi-led coalition assault on the port city of Hodeidah in Yemen. It was spearheaded by the United Arab Emirates and Saudi Arabia and was considered the largest battle since the start of the Saudi Arabian-led intervention in Yemen in 2015.', 2018, 9, 16, NULL, NULL, NULL, 'day', '16 September 2018', 41, 'https://en.wikipedia.org/wiki/Battle_of_Hodeidah'),
  ('Q79401903', 'Riyadh Agreement', 'The Riyadh Agreement (Arabic: اتفاق الرياض, romanized: Ittifāq ar-Riyāḏ) was signed on 5 November 2019 in the capital city of Saudi Arabia, Riyadh, between Abdrabbuh Mansur Hadi, representing the Saudi-backed government of Yemen, Muhammad bin Zayid Al Nahyan, representing the United Arab Emirates, and Aydarus al-Zubaydi, representing the UAE-backed Southern Transitional Council (STC). It followed the Southern Yemen clashes of August 2019, with the goal of ending the fighting and establishing a united front against the Iran-backed Houthi rebels, dominant in the north of the country.', 2019, 11, 5, NULL, NULL, NULL, 'day', '5 November 2019', 34, 'https://en.wikipedia.org/wiki/Riyadh_Agreement'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q126725725', '2024 Hajj disaster', 'Between 14 and 19 June 2024, at least 1,301 people on the Hajj pilgrimage died in Mecca, Saudi Arabia, due to extreme heat, with temperatures exceeding 50 °C (122 °F). Extreme heat caused heat stroke and dehydration among the pilgrims, leading to the deaths.', 2024, 6, 14, 2024, 6, 19, 'day', '14 June 2024 – 19 June 2024', 55, 'https://en.wikipedia.org/wiki/2024_Hajj_extreme_heat_disaster'),
  ('Q141655522', 'Operation Dawn of Yemen', 'On 3 September 2026, the Iran-backed Houthis launched an offensive against the Saudi-backed Presidential Leadership Council (PLC), the internationally recognized government of Yemen, amid the ongoing Yemeni civil war. Clashes began in Taiz Governorate, prompting a PLC counter-offensive against the Houthis in the Al-Jawf and Al-Bayda governorates.', 2026, 10, 5, NULL, NULL, NULL, 'day', '5 October 2026', 34, 'https://en.wikipedia.org/wiki/Operation_Dawn_of_Yemen');
